import os, glob, json, re

# Extract demo pairs from the session log
session_log = '/home/USER/runs/paper/qwen-hpl0-u1-window-light/frozen/stream-100/play/users/u041/system/state/sessions/01a1ad6b-cd98-749e-bdb4-0b96dc03059a.jsonl'
