    if 'Demo pair' in line or 'Test input' in line:
        match = re.search(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\)', line)
        if match:
            task_type = match.group(1)
            h, w = int(match.group(2)), int(match.group(3))

            # Get the grid from the next few lines
            lines = content.split('\n')
            idx = lines.index(line)
            grid_lines = lines[idx+1:idx+1+h]
            grid = [[int(x) for x in row.split()] for row in grid_lines]

            if task_type == 'Demo pair':
                demo_num = int(re.search(r'Demo pair (\d+)', line).group(1))
                demos[f"demo{demo_num}"] = {"input": grid, "output": None}
